    changes: list[dict[str, Any]] = []
    distance = 0
    for key, after in zip(editable, states):
        present = key in facts
        before = facts[key] if present else None
        if after is None:
            if present:
                del candidate[key]
                changes.append({"key": key, "before": before, "after": None})
                distance += 1
        elif not present or facts[key] is not after:
            candidate[key] = after
            changes.append({"key": key, "before": before, "after": after})
            distance += 1
    return candidate, changes, distance

def _decides(candidate: dict[str, bool]) -> bool:
    for rule in ranked:
        if _matches(rule, candidate):
            return rule["result"] == target
    return target is None

# First pass: find the minimum distance (matching is cheap; full
# explanations are only built in the second pass).
minimum: int | None = None
for states in itertools.product((None, False, True), repeat=len(editable)):
    candidate, _, distance = _scheme(states)
    if (minimum is None or distance < minimum) and _decides(candidate):
