        "distance": None,
        "counterfactuals": [],
    }

# Second pass: materialize the minimum-distance schemes and order them by
# key order, then the null, false, true order of before and after.
winners: list[tuple[tuple, dict[str, Any]]] = []
for states in itertools.product((None, False, True), repeat=len(editable)):
    candidate, changes, distance = _scheme(states)
